fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // If the array has zero or one element, it vacuously has only one distinct value.
    if arr.len() <= 1 {
        return true;
    }

    // Grab the first element to compare against.
    let first = arr[0];

    // Check every other element; if any differs, return false.
    for &x in &arr[1..] {
        if x != first {
            return false;
        }
    }

    // If we never found a differing element, return true.
    true
}

